    # Combine the four 3-row panels cellwise, with higher-priority colors
    # taking precedence: 5, then 4, then 8, then 2.
    out = []
    for r in range(3):
        row = []
        for c in range(len(grid[0])):
            v = next((grid[3 * band + r][c] for band in (0, 1, 3, 2)
